import {buildingPropPickFaces,pickBuildingProp} from './building-prop-picking.js?v=scenario-variable-manager-1';
import {PROP_CATEGORIES,BUILDING_PROPS,drawBuildingProps,rasterizePropPreview,addBuildingProp,removeBuildingProp,buildingPropGeometry} from './building-props.js?v=scenario-variable-manager-1';
import {projectedBuildingSurfaces,pickBuildingSurface} from './building-surface-picking.js?v=scenario-variable-manager-1';
import {projectBuildingPoint} from './building-footprints.js?v=scenario-variable-manager-1';
export function propPlacementSurfaces(design,rotation=0){
 if(!design.blocks&&!design.voxels)return[];
 const ground=Array.from({length:100},(_,i)=>{const x=i%10,y=Math.floor(i/10),a=(x-5)*.085,b=(y-5)*.085,points=[[a,b,0],[a+.085,b,0],[a+.085,b+.085,0],[a,b+.085,0]];return{x,y,index:i,side:4,points,polygon:points.map(p=>projectBuildingPoint(p,rotation,design.footprint))};});
 return [...ground,...projectedBuildingSurfaces(design,rotation)];
}
export function mountBuildingPropEditor(host,canvas,{get,camera,mode,apply,render,status}){
 host.innerHTML=`<label>Prop category<select data-prop-category>${PROP_CATEGORIES.map(c=>`<option ${c==='Flora'?'selected':''}>${c}</option>`).join('')}</select></label><label>Prop<select data-prop-kind>${Object.entries(BUILDING_PROPS).map(([key,p])=>`<option value="${key}">${p.category} · ${p.name}</option>`).join('')}</select></label><label>Prop direction<select data-prop-rotation>${['North','East','South','West'].map((name,i)=>`<option value="${i}">${name}</option>`).join('')}</select></label><figure class="building-prop-preview"><canvas data-prop-preview width="160" height="160" role="img"></canvas><figcaption data-prop-caption></figcaption></figure><p class="fine">Choose Place props, then click visible ground or a roof. Arrows move the target; Enter places. Shift on release or Escape cancels. Select existing prop picks its type and direction without editing. Choose Place props to reuse it. Erase props: drag over visible props and release to remove them in one undoable stroke, or use a Remove button below. Use the construction Undo/Redo buttons for props too. Props remain if their supporting blocks are removed.</p><div data-prop-list></div>`;
 const category=host.querySelector('[data-prop-category]'),kind=host.querySelector('[data-prop-kind]'),direction=host.querySelector('[data-prop-rotation]'),list=host.querySelector('[data-prop-list]'),preview=host.querySelector('[data-prop-preview]'),caption=host.querySelector('[data-prop-caption]');let hover=null,pending=null,listKey=null,geometry=null,eraseGeometry=null,previewKey=null;
 const base=Object.fromEntries(['onpointerdown','onpointermove','onpointerup','onpointercancel','onkeydown','onwheel'].map(k=>[k,canvas[k]])),oldChange=mode.onchange;
 function filter(){const previous=kind.value,entries=Object.entries(BUILDING_PROPS).filter(([,p])=>p.category===category.value);kind.innerHTML=entries.map(([key,p])=>`<option value="${key}">${p.name}</option>`).join('');kind.value=entries.some(([key])=>key===previous)?previous:entries[0][0];}
 category.value='Flora';filter();
 const erasing=()=>mode.value==='erase-prop',sampling=()=>mode.value==='select-prop',picking=()=>erasing()||sampling(),active=()=>mode.value==='prop'||picking(),point=e=>{const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};};
 function faces(){const d=get(),key=[d.blocks,d.voxels,d.blockGeometry,d.footprint,d.rotation];if(!geometry||key.some((v,i)=>v!==geometry.key[i]))geometry={key,faces:propPlacementSurfaces(d,d.rotation)};return geometry.faces;}
 function eraseTarget(){if(!hover)return null;const d=get(),key=JSON.stringify([d.blocks,d.voxels,d.blockGeometry,d.props,d.footprint,d.rotation]);if(!eraseGeometry||eraseGeometry.key!==key)eraseGeometry={key,faces:buildingPropPickFaces(d,d.rotation)};return pickBuildingProp(eraseGeometry.faces,hover,camera());}
 const target=()=>{if(picking())return eraseTarget();const face=hover?pickBuildingSurface(faces(),hover,camera()):null;return face?.side===4?face:null;};
 function message(){if(sampling()){const index=eraseTarget();status.textContent=index===null?'Point at a visible prop to select its type and direction.':`Select ${BUILDING_PROPS[get().props[index].kind].name}. The building will stay unchanged.`;return;}if(erasing()){const index=eraseTarget();status.textContent=index===null?'Point at a visible prop to remove it.':`Remove ${BUILDING_PROPS[get().props[index].kind].name}. Click or press Enter; Undo can restore it.`;return;}const face=target();status.textContent=face?`${BUILDING_PROPS[kind.value]?.name||'Prop'} · column ${face.x+1}, row ${face.y+1}. Click or press Enter to place.`:'Choose visible ground or a roof on a block/layer model.';}
 function place(face){if(sampling()){if(face!==null){const prop=get().props[face];category.value=BUILDING_PROPS[prop.kind].category;filter();kind.value=prop.kind;direction.value=String(prop.rotation);status.textContent=`Selected ${BUILDING_PROPS[prop.kind].name} and its direction. Choose Place props to reuse it. The building is unchanged.`;}else message();return;}if(erasing()){if(face!==null){apply(removeBuildingProp(get(),face));status.textContent='Prop removed from the draft. Undo can restore it.';}else message();return;}if(!face){message();return;}try{apply(addBuildingProp(get(),kind.value,face,Number(direction.value)));status.textContent='Prop placed in the draft. Apply the building to update your city.';}catch(error){status.textContent=error.message;}}
 function reset(){hover=null;pending=null;geometry=null;eraseGeometry=null;}
 mode.onchange=()=>{reset();oldChange?.();category.disabled=kind.disabled=direction.disabled=mode.value!=='prop';render();};category.onchange=()=>{pending=null;filter();message();render();};kind.onchange=direction.onchange=()=>{pending=null;message();render();};category.disabled=kind.disabled=direction.disabled=mode.value!=='prop';
 canvas.onpointerdown=e=>{if(!active())return base.onpointerdown?.(e);if(e.button!==0)return;e.preventDefault();canvas.focus({preventScroll:true});hover=point(e);pending={id:e.pointerId,face:target(),design:get(),camera:JSON.stringify(camera()),kind:kind.value,direction:direction.value,eraseIndices:new Set()};if(erasing()&&pending.face!==null)pending.eraseIndices.add(pending.face);canvas.setPointerCapture(e.pointerId);message();render();};
 canvas.onpointermove=e=>{if(!active())return base.onpointermove?.(e);hover=point(e);if(erasing()&&pending?.id===e.pointerId){const index=eraseTarget();if(index!==null)pending.eraseIndices.add(index);}message();if(erasing()&&pending?.eraseIndices.size)status.textContent=`${pending.eraseIndices.size} props marked for removal. Release to erase; Shift or Escape cancels.`;render();};
 canvas.onpointerup=e=>{if(!active())return base.onpointerup?.(e);if(pending?.id!==e.pointerId)return;const p=pending;pending=null;const d=get();if(!e.shiftKey&&p.kind===kind.value&&p.direction===direction.value&&p.camera===JSON.stringify(camera())&&['blocks','voxels','blockGeometry','props','footprint','rotation'].every(k=>p.design[k]===d[k])){if(erasing()&&p.eraseIndices.size){apply(d.props.filter((_,index)=>!p.eraseIndices.has(index)));status.textContent=`Removed ${p.eraseIndices.size} props from the draft. Undo restores the whole stroke.`;}else place(p.face);}render();};
 canvas.onpointercancel=e=>{if(!active())return base.onpointercancel?.(e);pending=null;render();};
 canvas.onwheel=e=>{pending=null;base.onwheel?.(e);};
 canvas.onkeydown=e=>{if(!active())return base.onkeydown?.(e);if(e.key==='Escape'){e.preventDefault();e.stopPropagation();reset();render();return;}if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter'].includes(e.key))return base.onkeydown?.(e);e.preventDefault();e.stopPropagation();pending=null;hover??={x:128,y:330};const step=e.shiftKey?24:8;if(e.key==='ArrowLeft')hover.x-=step;if(e.key==='ArrowRight')hover.x+=step;if(e.key==='ArrowUp')hover.y-=step;if(e.key==='ArrowDown')hover.y+=step;if(e.key==='Enter')place(target());else message();render();};
 return{reset,refresh(){const view=get().rotation||0,keyPreview=`${kind.value}:${direction.value}:${view}`;
 if(keyPreview!==previewKey){const raster=rasterizePropPreview(kind.value,Number(direction.value),view),ctx=preview.getContext('2d'),pixels=ctx.createImageData(160,160);pixels.data.set(raster.data);ctx.putImageData(pixels,0,0);const text=`${BUILDING_PROPS[kind.value].name} · facing ${['North','East','South','West'][Number(direction.value)]} · viewed from ${['North','East','South','West'][view]}`;preview.setAttribute('aria-label',text);caption.textContent=text;previewKey=keyPreview;}
 const props=get().props||[],key=JSON.stringify(props);if(key===listKey)return;listKey=key;list.innerHTML=props.length?`<p>${props.length} / 64 placed props</p>${props.map((p,i)=>`<div class="actions"><span>${BUILDING_PROPS[p.kind].name} · ${p.x+1}, ${p.y+1} · ${['North','East','South','West'][p.rotation]}</span><button data-remove-prop="${i}" aria-label="Remove ${BUILDING_PROPS[p.kind].name} at column ${p.x+1}, row ${p.y+1}">Remove</button></div>`).join('')}`:'<p>No props placed.</p>';list.querySelectorAll('[data-remove-prop]').forEach(button=>button.onclick=()=>{pending=null;apply(removeBuildingProp(get(),Number(button.dataset.removeProp)));status.textContent='Prop removed from the draft. Undo can restore it.';});},draw(ctx){if(!active())return;const face=target();if(picking()){const indices=new Set(erasing()&&pending?pending.eraseIndices:[]);if(face!==null)indices.add(face);if(indices.size)drawBuildingProps(ctx,get(),get().rotation,[...indices]);return;}if(face===null)return;const d=get(),footprint=d.footprint||{width:1,height:1};let prop;try{prop=picking()?d.props[face]:addBuildingProp({...d,props:[]},kind.value,face,Number(direction.value))[0];}catch{return;}const points=buildingPropGeometry(prop,footprint).flatMap(f=>f.points).map(([x,y,z])=>projectBuildingPoint([x/footprint.width,y/footprint.height,z],d.rotation,footprint));const x=Math.min(...points.map(p=>p[0])),y=Math.min(...points.map(p=>p[1])),right=Math.max(...points.map(p=>p[0])),bottom=Math.max(...points.map(p=>p[1]));ctx.save();ctx.strokeStyle=picking()?'#71afff':'#ffe180';ctx.lineWidth=1.2/camera().zoom;ctx.strokeRect(x,y,right-x,bottom-y);ctx.restore();}};
}
